import { digestReceizCanonicalV122 } from "./v122Canonical.js";
export async function createReceizSubjectMandateV122(input) {
    const normalized = { ...input, allowedCommandKinds: [...new Set(input.allowedCommandKinds)].sort(), worldIds: [...new Set(input.worldIds)].sort(), regionIds: [...new Set(input.regionIds)].sort() };
    const identity = await digestReceizCanonicalV122({ schema: "receiz.subject-mandate.identity.v122", ownerSubjectId: input.ownerSubjectId, workerSubjectId: input.workerSubjectId, nonce: input.nonce });
    const basis = { schema: "receiz.subject-mandate.v122", mandateId: `receiz:mandate:${identity}`, ...normalized };
    return Object.freeze({ ...basis, mandateDigest: await digestReceizCanonicalV122(basis) });
}
export async function validateReceizMandateUseV122(input) {
    const { mandateDigest, ...basis } = input.mandate;
    const invalid = (code) => ({ ok: false, code, writesOnFailure: 0 });
    if (await digestReceizCanonicalV122(basis) !== mandateDigest)
        return invalid("mandate_digest_mismatch");
    if (input.ownerHead !== input.mandate.expectedOwnerHead || input.workerHead !== input.mandate.expectedWorkerHead)
        return invalid("mandate_subject_head_mismatch");
    if (input.revocationHead !== input.mandate.revocationHead)
        return invalid("mandate_revoked_or_stale");
    if (BigInt(input.currentKai) > BigInt(input.mandate.expiresAtKai))
        return invalid("mandate_expired");
    if (!input.mandate.allowedCommandKinds.includes(input.commandKind))
        return invalid("mandate_command_out_of_scope");
    if (input.worldId && !input.mandate.worldIds.includes(input.worldId))
        return invalid("mandate_world_out_of_scope");
    if (input.regionId && !input.mandate.regionIds.includes(input.regionId))
        return invalid("mandate_region_out_of_scope");
    if (BigInt(input.resourcePhiMicro) > BigInt(input.mandate.maximumResourcePhiMicro) || BigInt(input.geometryUnits) > BigInt(input.mandate.maximumGeometryUnits))
        return invalid("mandate_limit_exceeded");
    return { ok: true, mandateDigest };
}
export function createReceizRemoteSubjectMandatesV122(request) {
    return Object.freeze({
        issue: (input) => request("/api/sdk/v1/subject-mandates/issue", { method: "POST", body: input }),
        state: (input) => request(`/api/sdk/v1/subject-mandates/${encodeURIComponent(input.mandateId)}`),
        revoke: (input) => request(`/api/sdk/v1/subject-mandates/${encodeURIComponent(input.mandateId)}/revoke`, { method: "POST", body: input }),
    });
}
