import { planReceizPrivateCommandV122 } from "./v122PrivateWorld.js";
import { planReceizMultiWorldTransactionV122 } from "./v122MultiWorld.js";
import { planReceizWorldCommandV122, planReceizWorldTransactionV122 } from "./v122Transactions.js";
export function createReceizRemoteWorldV122(request) {
    return Object.freeze({
        planCommandV122: planReceizWorldCommandV122,
        planTransactionV122: planReceizWorldTransactionV122,
        planPrivateCommand: planReceizPrivateCommandV122,
        validateTransaction: (transaction) => request("/api/sdk/v1/world/transactions/validate", { method: "POST", body: { transaction } }),
        executeTransactionV122: (input) => request("/api/sdk/v1/world/transactions/execute", { method: "POST", body: input }),
        execution: (input) => request(`/api/sdk/v1/world/${encodeURIComponent(input.worldId)}/executions/${encodeURIComponent(input.transactionId)}`),
        executionByIdempotencyKey: (input) => request(`/api/sdk/v1/world/${encodeURIComponent(input.worldId)}/executions/by-idempotency/${encodeURIComponent(input.idempotencyKey)}`),
        additionsV122: (input) => request(`/api/sdk/v1/world/${encodeURIComponent(input.worldId)}/additions${input.afterHead ? `?afterHead=${encodeURIComponent(input.afterHead)}` : ""}`),
        planMultiWorldTransaction: planReceizMultiWorldTransactionV122,
        executeMultiWorldTransaction: (input) => request("/api/sdk/v1/world/multi-world/execute", { method: "POST", body: input }),
    });
}
