import { createReceizGlobalCoordinationHttpTransport, } from "./globalCoordinationProtocol.js";
export function createReceizRemoteArtifactTransitionStore(options) {
    if (!options.namespace || !options.accessToken || options.commitDomain.scheme !== "receiz-commit-domain.v1") {
        throw new TypeError("REMOTE_TRANSITION_STORE_OPTIONS_REQUIRED");
    }
    const transport = options.transport ?? createReceizGlobalCoordinationHttpTransport({
        baseUrl: options.baseUrl ?? "https://receiz.com",
        accessToken: options.accessToken,
        ...(options.fetchImpl ? { fetchImpl: options.fetchImpl } : {}),
    });
    const scope = { namespace: options.namespace, commitDomain: options.commitDomain };
    return Object.freeze({
        commitDomain: options.commitDomain,
        async stageCandidate(candidate) {
            return await transport("transition.stage", { ...scope, candidate });
        },
        async resolveCandidate(artifactDigest) {
            return await transport("transition.resolve", { ...scope, artifactDigest });
        },
        async commitTransition(unit) {
            return await transport("transition.commit", { ...scope, unit });
        },
    });
}
