import { canonicalizeReceizConstitution, digestReceizConstitution, } from "./constitution.js";
const verifiedCheckpoints = new WeakSet();
function add(target, key, amount) {
    target[key] = (target[key] ?? 0) + amount;
}
function projected(state) {
    return {
        aliveAssets: [...state.aliveAssets].filter((asset) => !state.retiredAssets.has(asset)).sort(),
        retiredAssets: [...state.retiredAssets].sort(),
        revokedCapabilities: [...state.revokedCapabilities].sort(),
        ownership: Object.fromEntries(Object.entries(state.ownership).sort(([left], [right]) => left.localeCompare(right))),
        spending: Object.fromEntries(Object.entries(state.spending).sort(([left], [right]) => left.localeCompare(right))),
        rewardsByCause: Object.fromEntries(Object.entries(state.rewardsByCause).sort(([left], [right]) => left.localeCompare(right))),
        rewardTotals: Object.fromEntries(Object.entries(state.rewardTotals).sort(([left], [right]) => left.localeCompare(right))),
        injuries: Object.fromEntries(Object.entries(state.injuries).sort(([left], [right]) => left.localeCompare(right))),
        liabilities: Object.fromEntries(Object.entries(state.liabilities).sort(([left], [right]) => left.localeCompare(right))),
        settlements: Object.fromEntries(Object.entries(state.settlements).sort(([left], [right]) => left.localeCompare(right))),
        authority: { projectionIsProofAuthority: false, strongerTruth: "sealed-receiz-proof-object" },
    };
}
function conflict(history, records) {
    const retirements = new Map();
    const living = new Map();
    const owners = new Map();
    const rewards = new Map();
    for (const item of records) {
        const event = item.event;
        if (event.type === "asset.retired")
            retirements.set(event.assetId, [...(retirements.get(event.assetId) ?? []), item]);
        if (event.type === "asset.alive")
            living.set(event.assetId, [...(living.get(event.assetId) ?? []), item]);
        if (event.type === "ownership.assigned")
            owners.set(event.assetId, [...(owners.get(event.assetId) ?? []), item]);
        if (event.type === "reward.granted") {
            const prior = rewards.get(event.causeId);
            if (prior && prior.event.type === "reward.granted" && (prior.event.resourceId !== event.resourceId || prior.event.amount !== event.amount))
                return { ok: false, code: "REWARD_CAUSE_CONFLICT", causeId: event.causeId };
            rewards.set(event.causeId, item);
        }
    }
    for (const [assetId, retired] of retirements) {
        for (const alive of living.get(assetId) ?? []) {
            if (retired.some((retirement) => !history.isAncestor(alive.recordDigest, retirement.recordDigest)))
                return { ok: false, code: "STALE_LIVING_BRANCH", affectedAsset: assetId };
        }
    }
    for (const [assetId, assignments] of owners) {
        for (let leftIndex = 0; leftIndex < assignments.length; leftIndex += 1) {
            for (let rightIndex = leftIndex + 1; rightIndex < assignments.length; rightIndex += 1) {
                const left = assignments[leftIndex];
                const right = assignments[rightIndex];
                if (left.event.type !== "ownership.assigned" || right.event.type !== "ownership.assigned" || left.event.ownerId === right.event.ownerId)
                    continue;
                if (!history.isAncestor(left.recordDigest, right.recordDigest) && !history.isAncestor(right.recordDigest, left.recordDigest))
                    return { ok: false, code: "OWNERSHIP_CONTRADICTION", affectedAsset: assetId };
            }
        }
    }
    return null;
}
function apply(state, item) {
    const event = item.event;
    switch (event.type) {
        case "asset.alive":
            state.aliveAssets.add(event.assetId);
            return;
        case "asset.retired":
            state.retiredAssets.add(event.assetId);
            state.aliveAssets.delete(event.assetId);
            return;
        case "capability.revoked":
            state.revokedCapabilities.add(event.capabilityDigest);
            return;
        case "ownership.assigned":
            state.ownership[event.assetId] = event.ownerId;
            return;
        case "resource.spent":
            add(state.spending, event.resourceId, event.amount);
            return;
        case "reward.granted":
            if (!state.rewardsByCause[event.causeId]) {
                state.rewardsByCause[event.causeId] = { resourceId: event.resourceId, amount: event.amount };
                add(state.rewardTotals, event.resourceId, event.amount);
            }
            return;
        case "injury.recorded":
            add(state.injuries, event.assetId, event.amount);
            return;
        case "liability.recorded":
            add(state.liabilities, event.assetId, event.amount);
            return;
        case "settlement.recorded":
            add(state.settlements, event.assetId, event.amount);
            return;
    }
}
async function reduce(history, includeTrace) {
    const records = history.records();
    const denied = conflict(history, records);
    if (denied)
        return denied;
    const state = {
        aliveAssets: new Set(), retiredAssets: new Set(), revokedCapabilities: new Set(), ownership: {}, spending: {},
        rewardsByCause: {}, rewardTotals: {}, injuries: {}, liabilities: {}, settlements: {},
    };
    const trace = [];
    for (const item of records) {
        apply(state, item);
        if (includeTrace)
            trace.push({ recordDigest: item.recordDigest, stateDigest: await digestReceizConstitution(projected(state)) });
    }
    const projection = projected(state);
    return {
        ok: true,
        projection,
        stateDigest: await digestReceizConstitution(projection),
        historyRoot: await history.historyRoot(),
        trace,
    };
}
export async function replayReceizCausalHistory(history) {
    return reduce(history, true);
}
export async function mergeReceizCausalHistory(history) {
    const result = await reduce(history, false);
    if (!result.ok)
        return result;
    return { ok: true, projection: result.projection, stateDigest: result.stateDigest, historyRoot: result.historyRoot };
}
function checkpointBasis(value) {
    return value;
}
export async function createReceizCausalCheckpoint(history) {
    const replay = await replayReceizCausalHistory(history);
    if (!replay.ok)
        throw new Error(replay.code);
    const basis = {
        schema: "receiz.causal.checkpoint.v1",
        registryDigest: history.registryDigest,
        historyRoot: replay.historyRoot,
        headDigests: history.heads(),
        recordCount: history.records().length,
        stateDigest: replay.stateDigest,
        authority: { checkpointIsProofAuthority: false, strongerTruth: "sealed-receiz-proof-object" },
    };
    return { ...basis, checkpointDigest: await digestReceizConstitution(checkpointBasis(basis)) };
}
export function isReceizVerifiedCausalCheckpoint(value) {
    return typeof value === "object" && value !== null && verifiedCheckpoints.has(value);
}
export async function verifyReceizCausalCheckpoint(value, history) {
    if (typeof value !== "object" || value === null)
        return { ok: false, code: "CHECKPOINT_INVALID" };
    let supplied;
    try {
        supplied = canonicalizeReceizConstitution(value);
    }
    catch {
        return { ok: false, code: "CHECKPOINT_INVALID" };
    }
    const expected = await createReceizCausalCheckpoint(history);
    if (supplied !== canonicalizeReceizConstitution(expected))
        return { ok: false, code: "CHECKPOINT_MISMATCH" };
    const checkpoint = { ...expected, verifiedBy: "receiz.sdk.causal-checkpoint.v1" };
    verifiedCheckpoints.add(checkpoint);
    return { ok: true, checkpoint };
}
