export async function admitVaultAssetSuccessorForBank(previous:Uint8Array,next:Uint8Array,options:AssetBinding):Promise<VaultAssetProjection>{const a=privateAssetPacket(previous),b=privateAssetPacket(next),{native,roots}=await nativeOptions(options),{title}=await native.verifyVaultAssetSuccessor({previous:a,next:b},{roots});return assetProjection(b,title,native,options);}
export async function admitVaultAssetPreflightForBank(bytes:Uint8Array,expected:Pick<VaultAssetIntent,'assetId'|'sourceHead'>,options:NativeOptions={}):Promise<VaultAssetPreflight>{
 const p=vaultObject(decode(bytes),['schema','assetId','sourceHead','authoredOriginal','totalExactBytes','maxExactBytes','serializedClosureBytes','currentLineageBytes','currentLineageSteps','reservedSourceBytes']);if(p.schema!=='receiz.bank.vault-asset-original-preflight.v1'||p.assetId!==expected.assetId||p.sourceHead!==expected.sourceHead||!hash(p.assetId)||!hash(p.sourceHead)||!Number.isSafeInteger(p.reservedSourceBytes)||Number(p.reservedSourceBytes)<=0||!Number.isSafeInteger(p.currentLineageBytes)||Number(p.currentLineageBytes)<=0||!Number.isSafeInteger(p.currentLineageSteps)||Number(p.currentLineageSteps)<=0||p.maxExactBytes!==16777216||!Number.isSafeInteger(p.totalExactBytes)||Number(p.totalExactBytes)<0||Number(p.totalExactBytes)>16777216||p.serializedClosureBytes!==json(p.authoredOriginal).length)fail('PREFLIGHT_INVALID');
 if(p.authoredOriginal===null){if(p.totalExactBytes!==0)fail('PREFLIGHT_INVALID');}else{const {native,roots}=await nativeOptions(options),opened=await native.verifyVaultAssetAuthoredOriginal(p.authoredOriginal,{roots});if(opened.totalExactBytes!==p.totalExactBytes)fail('PREFLIGHT_INVALID');}return{assetId:p.assetId,sourceHead:p.sourceHead,authoredOriginalSha256:await vaultDigest(json(p.authoredOriginal)),reservedSourceBytes:Number(p.reservedSourceBytes)};
}
export async function admitVaultAssetResultForBank(packet:unknown,review:NativeAssetReview):Promise<VaultAssetResultAdmission>{const {receipt:r}=await(await import('../native-asset')).verifyNativeAssetSource(packet,review);return r.schema==='receiz.bank.native-asset-refusal.v1'?{status:'zero-write',requestId:r.review.request.requestId}:{status:'committed',requestId:r.review.request.requestId,assetId:r.assetAfter.id,sourceHead:r.assetAfter.sourceSha256,atKaiUPulse:r.kaiUPulse};}
export async function admitVaultAssetConsentForBank(proof:ReceizIdentityLoginProof,review:NativeAssetReview,key:VaultNativeKey){const p=vaultObject(proof,['schema','keyId','alg','challengeB64Url','signatureB64Url']),challengeB64Url=nativeAssetChallenge(review);if(p.schema!=='receiz.identity.login_proof.v1'||p.keyId!==key.keyId||review.keyId!==key.keyId||p.alg!==key.alg||p.challengeB64Url!==challengeB64Url||!await(await import('@receiz/sdk')).verifyReceizIdentityPublicKeyProjectionSignature({keyId:key.keyId,alg:key.alg,publicKeyRawB64u:key.publicKeyRawB64u,challengeB64Url,signatureB64Url:proof.signatureB64Url}))fail('CONSENT_INVALID');}
